'use strict';
// OpenContainer stand-in for node's build-generated
// lib/internal/deps/undici/undici.js.
//
// In real node this file is GENERATED by the build (the undici bundle from
// deps/undici) and provides — among ~200 exports — the lazy surface
// lib/http.js actually consumes:
//   WebSocket, CloseEvent, MessageEvent  (http.WebSocket & friends)
//   setGlobalDispatcher, getGlobalDispatcher, EnvHttpProxyAgent
//   (http.setGlobalProxyFromEnv — only when proxy env vars are set).
// The kernel does not ship the full undici: outbound HTTP rides the fetch
// bridge instead (kernel/http-fetch-client.ts). What IS here is a REAL
// WebSocket class — an RFC6455 client over the kernel's virtual TCP (guest
// loopback servers work end-to-end); outbound raw TCP to the internet is
// not a browser capability and is documented in COMPATIBILITY.md.

const { Buffer } = require('buffer');
const net = require('net');

/* ------------------------------------------------------------------ events */

class CloseEvent extends Event {
  constructor(type, init = {}) {
    super(type, init);
    this.wasClean = init.wasClean === true;
    this.code = init.code ?? 0;
    this.reason = init.reason ?? '';
  }
}

class MessageEvent extends Event {
  constructor(type, init = {}) {
    super(type, init);
    this.data = init.data ?? null;
    this.origin = init.origin ?? '';
    this.lastEventId = init.lastEventId ?? '';
    this.ports = init.ports ?? [];
  }
}

/* ------------------------------------------------------------- WebSocket */

const CONNECTING = 0;
const OPEN = 1;
const CLOSING = 2;
const CLOSED = 3;

class WebSocket {
  constructor(url, protocols) {
    if (!(this instanceof WebSocket)) return new WebSocket(url, protocols);
    this.url = String(url);
    this.protocol = '';
    this.extensions = '';
    this.binaryType = 'blob';
    this.readyState = CONNECTING;
    this._eventListeners = { open: [], message: [], close: [], error: [] };
    this._socket = null;
    this._headerBuf = '';
    this._handshakeDone = false;
    this._pendingFrames = [];
    this._closeCode = null;
    this._closeReason = '';

    const parsed = new URL(this.url);
    const secure = parsed.protocol === 'wss:' || parsed.protocol === 'https:';
    if (!secure && parsed.protocol !== 'ws:' && parsed.protocol !== 'http:') {
      throw new Error('The URL\'s protocol must be one of "ws:", "wss:", "http:", "https:".');
    }
    const port = Number(parsed.port || (secure ? 443 : 80));
    const host = parsed.hostname;
    const pathWithQuery = parsed.pathname + (parsed.search || '');

    let sub = '';
    if (protocols) {
      const list = Array.isArray(protocols) ? protocols : [protocols];
      sub = 'Sec-WebSocket-Protocol: ' + list.join(', ') + '\r\n';
    }
    const key = Buffer.from(crypto.getRandomValues(new Uint8Array(16))).toString('base64');
    const req =
      'GET ' + pathWithQuery + ' HTTP/1.1\r\n' +
      'Host: ' + (parsed.port ? parsed.host : parsed.hostname) + '\r\n' +
      'Upgrade: websocket\r\n' +
      'Connection: Upgrade\r\n' +
      'Sec-WebSocket-Key: ' + key + '\r\n' +
      sub +
      'Sec-WebSocket-Version: 13\r\n\r\n';

    const onfail = (message) => {
      if (this.readyState === CLOSED) return;
      this.readyState = CLOSED;
      this._emit('error', new Event('error', { message }));
      this._emit('close', new CloseEvent('close', { code: 1006, reason: message, wasClean: false }));
    };

    const socket = net.connect({ host, port });
    this._socket = socket;
    socket.on('connect', () => {
      socket.write(req, 'latin1');
    });
    socket.on('data', (chunk) => this._onData(chunk, onfail));
    socket.on('error', (err) => onfail('socket error: ' + (err && err.message || err)));
    socket.on('close', () => {
      if (this.readyState === OPEN) {
        this.readyState = CLOSED;
        this._emit('close', new CloseEvent('close', { code: 1006, reason: 'connection closed', wasClean: false }));
      } else if (this.readyState !== CLOSED) {
        onfail('connection closed');
      }
    });
  }

  get onopen() { return this._onopen || null; }
  set onopen(fn) { this._onopen = fn; }
  get onmessage() { return this._onmessage || null; }
  set onmessage(fn) { this._onmessage = fn; }
  get onclose() { return this._onclose || null; }
  set onclose(fn) { this._onclose = fn; }
  get onerror() { return this._onerror || null; }
  set onerror(fn) { this._onerror = fn; }

  addEventListener(type, fn) {
    if (this._eventListeners[type]) this._eventListeners[type].push(fn);
  }
  removeEventListener(type, fn) {
    const list = this._eventListeners[type] || [];
    const i = list.indexOf(fn);
    if (i >= 0) list.splice(i, 1);
  }

  send(data) {
    if (this.readyState !== OPEN) throw new Error('InvalidStateError: WebSocket is not open');
    const bytes = typeof data === 'string'
      ? Buffer.from(data, 'utf8')
      : Buffer.isBuffer(data) ? data : Buffer.from(data);
    this._sendFrame(typeof data === 'string' ? 0x1 : 0x2, bytes);
  }

  close(code, reason) {
    if (this.readyState === CLOSING || this.readyState === CLOSED) return;
    this.readyState = CLOSING;
    this._closeCode = typeof code === 'number' ? code : 1000;
    this._closeReason = String(reason || '');
    const payload = Buffer.alloc(2 + this._closeReason.length);
    payload[0] = (this._closeCode >> 8) & 0xff;
    payload[1] = this._closeCode & 0xff;
    for (let i = 0; i < this._closeReason.length; i++) payload[2 + i] = this._closeReason.charCodeAt(i);
    this._sendFrame(0x8, payload);
    const self = this;
    setTimeout(() => self._finishClose(self._closeCode || 1000, ''), 500);
  }

  /* ---------------- internals ---------------- */

  _emit(type, ev) {
    const handler = this['_on' + type];
    if (typeof handler === 'function') { try { handler.call(this, ev); } catch { /* app error */ } }
    const list = (this._eventListeners[type] || []).slice();
    for (const fn of list) { try { fn.call(this, ev); } catch { /* app error */ } }
  }

  _onData(chunk, onfail) {
    const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    if (!this._handshakeDone) {
      this._headerBuf += bytes.toString('latin1');
      const idx = this._headerBuf.indexOf('\r\n\r\n');
      if (idx < 0) return;
      const head = this._headerBuf.slice(0, idx);
      const rest = this._headerBuf.length - (idx + 4);
      const body = rest > 0 ? bytes.subarray(bytes.length - rest) : Buffer.alloc(0);
      if (!/^HTTP\/1\.1 101/.test(head)) {
        const statusLine = head.split('\r\n')[0] || '';
        onfail('WebSocket handshake failed: ' + statusLine);
        return;
      }
      const protoMatch = /Sec-WebSocket-Protocol:\s*(.+)/i.exec(head);
      if (protoMatch) this.protocol = protoMatch[1].trim();
      this._handshakeDone = true;
      this.readyState = OPEN;
      this._emit('open', new Event('open'));
      if (body.length > 0) this._consumeFrames(body);
      for (const f of this._pendingFrames) this._rawSend(f);
      this._pendingFrames.length = 0;
      return;
    }
    this._consumeFrames(bytes);
  }

  _consumeFrames(bytes) {
    let offset = 0;
    for (;;) {
      const frame = readFrame(bytes, offset);
      if (!frame) return;
      const payload = frame.payload;
      switch (frame.opcode) {
        case 0x1: // text
          this._emit('message', new MessageEvent('message', { data: payload.toString('utf8') }));
          break;
        case 0x2: // binary
          this._emit('message', new MessageEvent('message', {
            data: this.binaryType === 'arraybuffer'
              ? payload.buffer.slice(payload.byteOffset, payload.byteOffset + payload.length)
              : payload,
          }));
          break;
        case 0x8: { // close
          const code = payload.length >= 2 ? (payload[0] << 8) | payload[1] : 1005;
          const reason = payload.length > 2 ? payload.subarray(2).toString('utf8') : '';
          this._sendFrame(0x8, payload.subarray(0, Math.min(2, payload.length)));
          this._finishClose(code, reason);
          return;
        }
        case 0x9: // ping → pong
          this._sendFrame(0xA, payload);
          break;
        case 0xA: // pong
          break;
        default:
          break;
      }
      offset = frame.nextOffset;
    }
  }

  _sendFrame(opcode, payload) {
    const frame = buildClientFrame(opcode, payload);
    if (this.readyState === CONNECTING) {
      this._pendingFrames.push(frame);
      return;
    }
    this._rawSend(frame);
  }

  _rawSend(frame) {
    try { this._socket.write(frame, 'latin1'); }
    catch (e) { this._emit('error', new Event('error', { message: 'send failed: ' + e.message })); }
  }

  _finishClose(code, reason) {
    if (this.readyState === CLOSED) return;
    this.readyState = CLOSED;
    try { this._socket && this._socket.end(); } catch { /* noop */ }
    this._emit('close', new CloseEvent('close', { code, reason, wasClean: true }));
  }
}

WebSocket.CONNECTING = CONNECTING;
WebSocket.OPEN = OPEN;
WebSocket.CLOSING = CLOSING;
WebSocket.CLOSED = CLOSED;

/** Client frames are MASKED (RFC6455 §5.3). */
function buildClientFrame(opcode, payload) {
  const maskKey = crypto.getRandomValues(new Uint8Array(4));
  const len = payload.length;
  let headerLen;
  let head;
  if (len < 126) {
    headerLen = 2;
    head = Buffer.alloc(headerLen);
    head[1] = 0x80 | len;
  } else if (len < 65536) {
    headerLen = 4;
    head = Buffer.alloc(headerLen);
    head[1] = 0x80 | 126;
    head[2] = (len >> 8) & 0xff;
    head[3] = len & 0xff;
  } else {
    headerLen = 10;
    head = Buffer.alloc(headerLen);
    head[1] = 0x80 | 127;
    const hi = Math.floor(len / 4294967296);
    head[2] = (hi >> 24) & 0xff; head[3] = (hi >> 16) & 0xff;
    head[4] = (hi >> 8) & 0xff; head[5] = hi & 0xff;
    head[6] = (len >> 24) & 0xff; head[7] = (len >> 16) & 0xff;
    head[8] = (len >> 8) & 0xff; head[9] = len & 0xff;
  }
  head[0] = 0x80 | opcode;
  head.set(maskKey, headerLen - 4);
  const out = Buffer.alloc(headerLen + len);
  head.copy(out, 0);
  for (let i = 0; i < len; i++) out[headerLen + i] = payload[i] ^ maskKey[i & 3];
  return out;
}

/** Read one (unmasked, server→client) frame at offset; null if incomplete.
 *  Returns { opcode, payload, nextOffset } on success. */
function readFrame(bytes, offset) {
  if (bytes.length - offset < 2) return null;
  const b0 = bytes[offset];
  const b1 = bytes[offset + 1];
  const opcode = b0 & 0x0f;
  const masked = (b1 & 0x80) !== 0;
  let len = b1 & 0x7f;
  let at = offset + 2;
  if (len === 126) {
    if (bytes.length - at < 2) return null;
    len = (bytes[at] << 8) | bytes[at + 1];
    at += 2;
  } else if (len === 127) {
    if (bytes.length - at < 8) return null;
    len = 0;
    for (let i = 0; i < 8; i++) len = len * 256 + bytes[at + i];
    at += 8;
  }
  let maskKey = null;
  if (masked) {
    if (bytes.length - at < 4) return null;
    maskKey = bytes.subarray(at, at + 4);
    at += 4;
  }
  if (bytes.length - at < len) return null;
  let payload = bytes.subarray(at, at + len);
  if (masked) {
    const un = Buffer.alloc(len);
    for (let j = 0; j < len; j++) un[j] = payload[j] ^ maskKey[j & 3];
    payload = un;
  }
  return { opcode, payload, nextOffset: at + len };
}

/* --------------------------------------------------- dispatcher registry */
/* Only touched by http.setGlobalProxyFromEnv when proxy env vars are set —
 * the fetch bridge handles all outbound HTTP; a real proxy chain is not a
 * browser capability. The registry exists so the API shape holds. */

let globalDispatcher = null;
function EnvHttpProxyAgent() { /* no-op constructor (proxy env unsupported) */ }
function setGlobalDispatcher(agent) { globalDispatcher = agent; return globalDispatcher; }
function getGlobalDispatcher() { return globalDispatcher; }

module.exports = {
  WebSocket,
  CloseEvent,
  MessageEvent,
  setGlobalDispatcher,
  getGlobalDispatcher,
  EnvHttpProxyAgent,
};
